-- =========================================================================
-- Seed the 158 IT/HR tests from framework.xlsx. Resolves control_id by
-- joining controls.code (controls themselves seeded in 033). UPSERT keeps
-- name, control link, GRC fields, and the pass/fail/freq columns in sync.
--
-- Frequency mapping: checks.frequency is an enum, so we map the free-form
-- label ('Monthly / Quarterly', 'Per release / Monthly') to the closest
-- bucket; the original label is preserved verbatim in frequency_label.
-- =========================================================================

INSERT INTO checks (
  code, name, description, control_id, frequency, is_active,
  procedure_steps, method, performer_role, reviewer_role,
  pass_criteria, fail_criteria, frequency_label
)
SELECT v.code, v.name, NULL, c.id, v.frequency, TRUE,
       v.procedure_steps, v.method, v.performer_role, v.reviewer_role,
       v.pass_criteria, v.fail_criteria, v.frequency_label
FROM (VALUES
  ('IT-INFO-TEST-001-01', 'Review evidence for Access Rights & Permissions Control', 'IT-INFO-CTRL-001', 'monthly', 'Review the latest Access Rights & Permissions Matrix. Check owner, date, status, approvals, open items, and closure evidence.', 'Document review', 'IT / Control Owner', 'Compliance / IT Manager', 'Evidence exists, is current, complete, and reviewed by the assigned owner.', 'Evidence missing, outdated, incomplete, or not reviewed.', 'Monthly / Quarterly'),
